package com.distributedexam.client.ui;
import com.distributedexam.client.RMIClientConnector; import com.distributedexam.common.*; import javax.swing.*; import java.awt.*;
public class LoginFrame extends JFrame { private final JTextField username=new JTextField(18);private final JPasswordField password=new JPasswordField(18);private final RMIClientConnector connector;
 public LoginFrame(String host,int port){super("Exam Monitor Login");connector=new RMIClientConnector(host,port);setDefaultCloseOperation(EXIT_ON_CLOSE);JPanel p=new JPanel(new GridLayout(3,2,8,8));p.setBorder(BorderFactory.createEmptyBorder(18,18,18,18));p.add(new JLabel("Username"));p.add(username);p.add(new JLabel("Password"));p.add(password);JButton login=new JButton("Login");login.addActionListener(e->login());p.add(login);add(p);pack();setLocationRelativeTo(null);} private void login(){try{connector.connect();User u=connector.getAuthService().login(username.getText().trim(),new String(password.getPassword()));if(u==null){JOptionPane.showMessageDialog(this,"Invalid username or password.");return;}dispose();if(u.getRole()==UserRole.ADMIN||u.getRole()==UserRole.COORDINATOR)new CoordinatorDashboard(connector,u).setVisible(true);else new RoomDashboard(connector,u).setVisible(true);}catch(Exception e){JOptionPane.showMessageDialog(this,"Could not authenticate through RMI: "+e.getMessage(),"Login failed",JOptionPane.ERROR_MESSAGE);}} public static void main(String[] a){SwingUtilities.invokeLater(()->new LoginFrame(a.length>0?a[0]:"localhost",1099).setVisible(true));}}
